CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE autonomy_level AS ENUM ('advisor','operator','autopilot','developer');
CREATE TYPE risk_class AS ENUM ('read','low','medium','high','forbidden');
CREATE TYPE record_status AS ENUM ('pending','running','completed','failed','cancelled');
CREATE TYPE approval_status AS ENUM ('pending','approved','denied','expired','cancelled');

CREATE TABLE guilds (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), discord_id text UNIQUE NOT NULL, name text, settings jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), discord_id text UNIQUE NOT NULL, username text, profile jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), guild_id uuid REFERENCES guilds ON DELETE CASCADE, channel_id text NOT NULL, thread_id text, status text NOT NULL DEFAULT 'active', metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX conversations_context_idx ON conversations(guild_id,channel_id,thread_id);
CREATE TABLE messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES conversations ON DELETE CASCADE, discord_id text UNIQUE NOT NULL, author_id uuid REFERENCES users, content text, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX messages_conversation_idx ON messages(conversation_id,created_at DESC);
CREATE TABLE message_revisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), message_id uuid NOT NULL REFERENCES messages ON DELETE CASCADE, revision integer NOT NULL, content text, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(message_id,revision));
CREATE TABLE memories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), guild_id uuid REFERENCES guilds ON DELETE CASCADE, user_id uuid REFERENCES users ON DELETE CASCADE, kind text NOT NULL, content text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX memories_scope_idx ON memories(guild_id,user_id,kind);
CREATE TABLE tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), guild_id uuid REFERENCES guilds, actor_id uuid REFERENCES users, domain text NOT NULL, risk risk_class NOT NULL, status record_status NOT NULL DEFAULT 'pending', goal text NOT NULL, idempotency_key text UNIQUE NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE task_steps (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), task_id uuid NOT NULL REFERENCES tasks ON DELETE CASCADE, position integer NOT NULL, kind text NOT NULL, status record_status NOT NULL DEFAULT 'pending', input jsonb NOT NULL DEFAULT '{}', output jsonb, error jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(task_id,position));
CREATE TABLE tool_invocations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), task_id uuid REFERENCES tasks ON DELETE CASCADE, step_id uuid REFERENCES task_steps ON DELETE CASCADE, tool_name text NOT NULL, idempotency_key text UNIQUE NOT NULL, status record_status NOT NULL DEFAULT 'pending', input jsonb NOT NULL DEFAULT '{}', output jsonb, error jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE evidence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), task_id uuid REFERENCES tasks ON DELETE CASCADE, step_id uuid REFERENCES task_steps ON DELETE CASCADE, invocation_id uuid REFERENCES tool_invocations ON DELETE CASCADE, kind text NOT NULL, uri text, payload jsonb, sha256 text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), guild_id uuid REFERENCES guilds, actor_id uuid REFERENCES users, action text NOT NULL, domain text NOT NULL, risk risk_class NOT NULL, decision text NOT NULL, reason text, correlation_id uuid, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_scope_idx ON audit(guild_id,created_at DESC);
CREATE TABLE autonomy_policies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), guild_id uuid NOT NULL REFERENCES guilds ON DELETE CASCADE, domain text NOT NULL, level autonomy_level NOT NULL DEFAULT 'advisor', config jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(guild_id,domain));
CREATE TABLE approvals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), task_id uuid REFERENCES tasks ON DELETE CASCADE, guild_id uuid NOT NULL REFERENCES guilds ON DELETE CASCADE, requested_by uuid REFERENCES users, decided_by uuid REFERENCES users, status approval_status NOT NULL DEFAULT 'pending', reason text, expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE budgets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), guild_id uuid NOT NULL REFERENCES guilds ON DELETE CASCADE, domain text NOT NULL, period text NOT NULL, limit_amount numeric(18,6) NOT NULL CHECK(limit_amount>=0), spent_amount numeric(18,6) NOT NULL DEFAULT 0 CHECK(spent_amount>=0), currency text NOT NULL DEFAULT 'USD', resets_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(guild_id,domain,period));
